package org.brightstats.desktop;
import java.util.*;import com.google.gson.*;import javafx.scene.control.*;import javafx.scene.layout.*;import javafx.geometry.Insets;import javafx.stage.Window;import org.brightstats.stats.*;import org.brightstats.data.*;
final class RegularizedDialog {
 private RegularizedDialog(){}
 record Settings(SemModel.Model model,RegularizedSem.Options options){Settings{Objects.requireNonNull(model);Objects.requireNonNull(options);}}
 static Settings read(JsonElement value){if(value==null||value.isJsonNull())return null;var o=StatisticalInput.object(value,Set.of("model","options"),"regularization settings",false);return new Settings(SemModelInput.model(o.get("model")),RegularizedInput.options(o.get("options")));}
 static Optional<Settings> show(Window owner,SemModel.Model model,RegularizedSem.Options previous){return new Editor(owner,model,previous).dialog.showAndWait();}
 private static final class Editor {
  final Dialog<Settings> dialog=new Dialog<>();final TextField lambdas=new TextField("0, 0.01, 0.1, 0.5"),mixing=new TextField("1"),outer=new TextField("3"),inner=new TextField("3"),seed=new TextField("42"),iterations=new TextField("3000"),tolerance=new TextField("0.0000001"),active=new TextField("0.000001");final Label error=new Label();Settings result;
  Editor(Window owner,SemModel.Model model,RegularizedSem.Options previous){dialog.initOwner(owner);dialog.setTitle("Regularized SEM and nested validation");dialog.setResizable(true);dialog.getDialogPane().getButtonTypes().setAll(ButtonType.OK,ButtonType.CANCEL);if(previous!=null){lambdas.setText(Arrays.toString(previous.lambdas()).replaceAll("[\\[\\]]",""));mixing.setText(Double.toString(previous.mixing()));outer.setText(Integer.toString(previous.outerFolds()));inner.setText(Integer.toString(previous.innerFolds()));seed.setText(Long.toString(previous.seed()));iterations.setText(Integer.toString(previous.maxIterations()));tolerance.setText(Double.toString(previous.tolerance()));active.setText(Double.toString(previous.selectionTolerance()));}Map<String,RegularizedSem.Target> old=new HashMap<>();if(previous!=null)previous.targets().forEach(t->old.put(t.parameter(),t));List<SemModel.Parameter> parameters=model.parameters().stream().filter(p->p.locations().stream().allMatch(l->l.kind()==SemModel.Kind.DIRECTED)).toList();List<CheckBox> choices=new ArrayList<>();List<TextField> centers=new ArrayList<>(),scales=new ArrayList<>();GridPane targets=new GridPane();targets.setHgap(12);targets.setVgap(8);targets.addRow(0,new Label("Penalize path / loading"),new Label("Fixed raw-unit center"),new Label("Fixed raw-unit scale"));for(int j=0;j<parameters.size();j++){String name=parameters.get(j).name();var saved=old.get(name);CheckBox choice=new CheckBox(name);choice.setSelected(previous==null||saved!=null);TextField center=new TextField(saved==null?"0":Double.toString(saved.center())),scale=new TextField(saved==null?"1":Double.toString(saved.scale()));center.setAccessibleText("Penalty center: "+name);scale.setAccessibleText("Penalty scale: "+name);targets.addRow(j+1,choice,center,scale);choices.add(choice);centers.add(center);scales.add(scale);}Label note=new Label("Elastic-net regularization shrinks selected directed paths/loadings. Scales and centers must be fixed scientific choices, independent of held-out outcomes. Outer folds evaluate the entire inner-CV selection procedure. The final fit selects lambda in a separate full-data inner CV. Every failed candidate fold is reported; no post-selection P values or ordinary SE are claimed. Complete selected continuous data are required.");note.setWrapText(true);note.setMaxWidth(800);GridPane grid=new GridPane();grid.setHgap(12);grid.setVgap(8);TextField[] fields={lambdas,mixing,outer,inner,seed,iterations,tolerance,active};String[] labels={"Lambda grid, including zero","Mixing: 0 ridge, 1 lasso","Outer folds","Inner folds","Seed","Maximum proximal iterations","Gradient-mapping tolerance","Scaled activity tolerance"};for(int i=0;i<fields.length;i++){grid.addRow(i,new Label(labels[i]),fields[i]);fields[i].setAccessibleText(labels[i]);}VBox content=new VBox(14,note,targets,new Separator(),grid,error);content.setPadding(new Insets(14));ScrollPane scroll=new ScrollPane(content);scroll.setFitToWidth(true);scroll.setPrefViewportWidth(830);scroll.setPrefViewportHeight(600);dialog.getDialogPane().setContent(scroll);dialog.getDialogPane().lookupButton(ButtonType.OK).addEventFilter(javafx.event.ActionEvent.ACTION,event->{try{List<RegularizedSem.Target> selected=new ArrayList<>();for(int j=0;j<choices.size();j++)if(choices.get(j).isSelected())selected.add(new RegularizedSem.Target(parameters.get(j).name(),Double.parseDouble(centers.get(j).getText().strip()),Double.parseDouble(scales.get(j).getText().strip())));double[] gridValues=Arrays.stream(lambdas.getText().split(",",-1)).map(String::strip).mapToDouble(Double::parseDouble).toArray();result=new Settings(model,new RegularizedSem.Options(selected,gridValues,Double.parseDouble(mixing.getText().strip()),Integer.parseInt(outer.getText().strip()),Integer.parseInt(inner.getText().strip()),Long.parseLong(seed.getText().strip()),Integer.parseInt(iterations.getText().strip()),Double.parseDouble(tolerance.getText().strip()),Double.parseDouble(active.getText().strip())));}catch(RuntimeException invalid){error.setText(invalid.getMessage());event.consume();}});dialog.setResultConverter(button->button==ButtonType.OK?result:null);}
 }
 static Settings smoke(Window owner,Settings current){var editor=new Editor(owner,current.model(),current.options());editor.dialog.show();editor.lambdas.setText("0.1, 0.2");((Button)editor.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(!editor.dialog.isShowing())throw new AssertionError("Lambda grid without baseline accepted");editor.lambdas.setText(Arrays.toString(current.options().lambdas()).replaceAll("[\\[\\]]",""));((Button)editor.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();return Objects.requireNonNull(editor.dialog.getResult());}
}
